"""Ten-year diagnostic, not a target. All amounts USD bn; shares bn.
Opening physical capital and legacy liabilities unresolved: grid, not central point.
"""
import json,pathlib,csv
P=pathlib.Path(__file__).parent
R={'revenue':169.803,'cash':23.116,'minimum_cash':18,'gross_auto_debt':16.148,'industrial_nci':.696,'shares_proxy':.864,'gmf_common_capital':14.194,'gmf_common_ttm_income':1.775,'auto_ttm_da':6.812,'auto_book_ppe':54.657}
rf=.0486;erp=.0441;beta=1.42;ke=rf+erp*beta;wacc=ke*.8+(rf+.0155)*.75*.2
cases={'adverso':{'growth':[-.06,0,.01,.015,.015]+[.01]*5,'margins':[.04,.045,.05,.05,.05]+[.05]*5,'wacc':.12,'g':.01,'capex_floor':.045,'transition':[2,1,.5,.25]+[0]*6,'gmf_earn':1.35,'gmf_ke':.14},'referencia_no_calibrada':{'growth':[.02]*10,'margins':[.065,.066,.067,.068]+[.068]*6,'wacc':wacc,'g':.02,'capex_floor':.047,'transition':[1.5,1,.5,.25]+[0]*6,'gmf_earn':1.775,'gmf_ke':.125},'favorable':{'growth':[.04,.035,.03,.025,.025]+[.025]*5,'margins':[.075,.078,.08]+[.08]*7,'wacc':.09,'g':.025,'capex_floor':.048,'transition':[1,.5,.25]+[0]*7,'gmf_earn':2.1,'gmf_ke':.115}}
# These are broad analyst sensitivity boundaries, NOT sourced asset values / actuarial reserve.
physical_grid=[60,80,100];reserve_grid=[4,8,12];life_grid=[8,10,12]
def run(c,opening,reserve,life):
 revenue=R['revenue'];initial=opening;vintages=[];physical=opening;nwc=.10*revenue;pv=0;rows=[]
 for i in range(10):
  previous=revenue;revenue*=1+c['growth'][i]
  # Existing pool consumes TTM depreciation until exhausted; new capex depreciates next year, SL.
  initial_da=min(initial,R['auto_ttm_da']);initial-=initial_da
  vintage_da=sum(min(v['book'],v['cost']/life) for v in vintages)
  for v in vintages:v['book']-=min(v['book'],v['cost']/life)
  da=initial_da+vintage_da
  # No capital is generated by higher margin. Growth capacity needs revenue/2.5; maintenance funds DA.
  capacity_add=max(0,revenue-previous)/2.5
  floor=revenue*c['capex_floor']
  # Early onshoring/EV program retains 6.2% minimum for reference/favorable; fade by year 5.
  if i<4:floor=max(floor,revenue*(.062-(.062-c['capex_floor'])*i/4))
  capex=max(floor,da+capacity_add)
  physical=physical-da+capex;vintages.append({'cost':capex,'book':capex})
  delta_nwc=.10*(revenue-previous);nwc+=delta_nwc;nopat=revenue*c['margins'][i]*.75
  fcff=nopat+da-capex-delta_nwc-c['transition'][i];pv+=fcff/(1+c['wacc'])**(i+1)
  rows.append(dict(year=2027+i,revenue=revenue,nopat=nopat,da=da,capex=capex,net_physical=physical,nwc=nwc,delta_nwc=delta_nwc,transition=c['transition'][i],fcff=fcff,initial_pool_remaining=initial))
 # Terminal grows actual funded physical capital and NWC. Maintenance equals DA; no cash-free growth.
 ic=physical+nwc;nopat_next=rows[-1]['nopat']*(1+c['g']);reinvest=ic*c['g'];terminal_fcff=nopat_next-reinvest;tv=terminal_fcff/(c['wacc']-c['g']);ev=pv+tv/(1+c['wacc'])**10
 capital=R['gmf_common_capital'];earn=c['gmf_earn'];finance_pv=0;finance=[]
 for t in range(1,11):
  if t>1:earn*=1+c['g']
  retain=capital*c['g'];div=earn-retain;capital+=retain;finance_pv+=div/(1+c['gmf_ke'])**t;finance.append({'year':2026+t,'earn':earn,'retained':retain,'dividend':div,'closing_capital':capital})
 terminal_div=earn*(1+c['g'])-capital*c['g'];finance_pv+=terminal_div/(c['gmf_ke']-c['g'])/(1+c['gmf_ke'])**10
 # Gross debt offsets GMF's corresponding intercompany claim; do not also remove claim from GMF.
 equity=ev+finance_pv+(R['cash']-R['minimum_cash'])-R['gross_auto_debt']-R['industrial_nci']-reserve
 return {'opening_physical_assumed':opening,'legacy_reserve_assumed':reserve,'new_asset_life_assumed':life,'industrial_ev':ev,'gmf_equity':finance_pv,'equity':equity,'diagnostic_value':equity/R['shares_proxy'],'terminal_invested_capital':ic,'terminal_roic_derived':nopat_next/ic,'terminal_reinvestment':reinvest,'terminal_fcff':terminal_fcff,'terminal_pv_share':(tv/(1+c['wacc'])**10)/ev,'forecast':rows,'finance_forecast':finance}
outputs={}
for name,c in cases.items():
 grid=[run(c,p,r,l) for p in physical_grid for r in reserve_grid for l in life_grid]
 outputs[name]={'diagnostic_min':min(v['diagnostic_value'] for v in grid),'diagnostic_max':max(v['diagnostic_value'] for v in grid),'grid':grid}
result={'ticker':'GM','as_of':'2026-11-08','status':'diagnostic_partial','stage3_complete':False,'entry_approved':False,'approved_valuation':None,'bear':None,'base':None,'bull':None,'reported':R,'discount':{'rf':rf,'erp':erp,'beta':beta,'ke':ke,'wacc_reference':wacc,'debt_spread_proxy':.0155},'uncertain_sensitivity_ranges':{'opening_physical':physical_grid,'legacy_reserve':reserve_grid,'new_asset_life':life_grid},'cases':cases,'outputs':outputs,'warning':'No calibrated point values. Opening physical base, vintage ages and pension/legacy reserve are unresolved. Ranges are hypothetical sensitivity envelopes, not fair-value confidence bounds.'}
# Hold operating reference fixed; unknown physical/reserve/life remain crossed, no preferred point.
discount_sensitivity=[]
for w in [.09,wacc,.11,.12]:
 for g in [.01,.02,.025]:
  c={**cases['referencia_no_calibrada'],'wacc':w,'g':g}
  grid=[run(c,p,r,l) for p in physical_grid for r in reserve_grid for l in life_grid]
  discount_sensitivity.append({'wacc':w,'g':g,'diagnostic_min':min(v['diagnostic_value'] for v in grid),'diagnostic_max':max(v['diagnostic_value'] for v in grid)})
result['fixed_operating_reference_discount_sensitivity']=discount_sensitivity
(P/'results.json').write_text(json.dumps(result,indent=2))
with (P/'diagnostic_grid.csv').open('w') as f:
 keys=['case','opening_physical_assumed','legacy_reserve_assumed','new_asset_life_assumed','diagnostic_value','industrial_ev','gmf_equity','terminal_roic_derived','terminal_pv_share'];w=csv.DictWriter(f,fieldnames=keys);w.writeheader()
 for name,o in outputs.items():
  for v in o['grid']:w.writerow({'case':name,**{k:v[k] for k in keys if k!='case'}})
print({k:(round(v['diagnostic_min'],2),round(v['diagnostic_max'],2)) for k,v in outputs.items()})
